import{_ as s,c as a,o as e,a as n}from"./app.013a12f3.js";const C=JSON.parse('{"title":"Handling Test Data and State in Playwright","description":"","frontmatter":{},"headers":[{"level":2,"title":"Common Problem Areas","slug":"common-problem-areas","link":"#common-problem-areas","children":[]},{"level":2,"title":"Hardcoded vs Dynamic Test Data","slug":"hardcoded-vs-dynamic-test-data","link":"#hardcoded-vs-dynamic-test-data","children":[]},{"level":2,"title":"API Setup vs UI Setup","slug":"api-setup-vs-ui-setup","link":"#api-setup-vs-ui-setup","children":[]},{"level":2,"title":"API vs Database Seeding","slug":"api-vs-database-seeding","link":"#api-vs-database-seeding","children":[]},{"level":2,"title":"Test Independence","slug":"test-independence","link":"#test-independence","children":[]},{"level":2,"title":"Cleanup Strategy","slug":"cleanup-strategy","link":"#cleanup-strategy","children":[]},{"level":2,"title":"Authentication State","slug":"authentication-state","link":"#authentication-state","children":[]},{"level":2,"title":"Parallel Execution","slug":"parallel-execution","link":"#parallel-execution","children":[]},{"level":2,"title":"Recommended Structure","slug":"recommended-structure","link":"#recommended-structure","children":[]},{"level":2,"title":"Final Takeaway","slug":"final-takeaway","link":"#final-takeaway","children":[]}],"relativePath":"blogs/handling-test-data-and-state-in-playwright.md"}'),l={name:"blogs/handling-test-data-and-state-in-playwright.md"},t=n(`<h1 id="handling-test-data-and-state-in-playwright" tabindex="-1">Handling Test Data and State in Playwright <a class="header-anchor" href="#handling-test-data-and-state-in-playwright" aria-hidden="true">#</a></h1><p>Many flaky automation issues are blamed on Playwright, but in most cases, the real problem is poor test data management.</p><p>Random failures, broken parallel execution, locked shared users, and tests that depend on execution order usually indicate uncontrolled test state\u2014not a tooling issue.</p><p>A scalable automation framework treats test data as part of the architecture.</p><h2 id="common-problem-areas" tabindex="-1">Common Problem Areas <a class="header-anchor" href="#common-problem-areas" aria-hidden="true">#</a></h2><p>Many teams start with shortcuts like hardcoded users or UI-based setup:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki"><code><span class="line"><span style="color:#89DDFF;">await</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">login</span><span style="color:#A6ACCD;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">testuser1</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">,</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">password</span><span style="color:#89DDFF;">&#39;</span><span style="color:#A6ACCD;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span></code></pre></div><p>This may work initially, but it becomes unstable over time when:</p><ul><li>credentials change</li><li>hared accounts get locked</li><li>multiple tests modify the same data</li><li>parallel execution causes collisions</li></ul><p>These patterns create fragile automation.</p><h2 id="hardcoded-vs-dynamic-test-data" tabindex="-1">Hardcoded vs Dynamic Test Data <a class="header-anchor" href="#hardcoded-vs-dynamic-test-data" aria-hidden="true">#</a></h2><p>Hardcoded data is acceptable for simple read-only validations or smoke checks:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki"><code><span class="line"><span style="color:#C792EA;">const</span><span style="color:#A6ACCD;"> user </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#A6ACCD;">  </span><span style="color:#F07178;">email</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">qa@test.com</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#A6ACCD;">  </span><span style="color:#F07178;">password</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">Password123</span><span style="color:#89DDFF;">&#39;</span></span>
<span class="line"><span style="color:#89DDFF;">};</span></span>
<span class="line"></span></code></pre></div><p>But for most functional automation, dynamic test data is the safer approach:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki"><code><span class="line"><span style="color:#C792EA;">const</span><span style="color:#A6ACCD;"> user </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#A6ACCD;">  </span><span style="color:#F07178;">email</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">\`</span><span style="color:#C3E88D;">user-</span><span style="color:#89DDFF;">\${</span><span style="color:#A6ACCD;">crypto</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">randomUUID</span><span style="color:#A6ACCD;">()</span><span style="color:#89DDFF;">}</span><span style="color:#C3E88D;">@test.com</span><span style="color:#89DDFF;">\`</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#A6ACCD;">  </span><span style="color:#F07178;">password</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">Password123</span><span style="color:#89DDFF;">&#39;</span></span>
<span class="line"><span style="color:#89DDFF;">};</span></span>
<span class="line"></span></code></pre></div><p>Dynamic data makes tests:</p><ul><li>independent</li><li>parallel-safe</li><li>reusable</li><li>scalable</li></ul><p>A better practice is to centralize test data creation using a factory pattern:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki"><code><span class="line"><span style="color:#89DDFF;">export</span><span style="color:#A6ACCD;"> </span><span style="color:#C792EA;">const</span><span style="color:#A6ACCD;"> userFactory </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">()</span><span style="color:#A6ACCD;"> </span><span style="color:#C792EA;">=&gt;</span><span style="color:#A6ACCD;"> (</span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#A6ACCD;">  </span><span style="color:#F07178;">email</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">\`</span><span style="color:#C3E88D;">user-</span><span style="color:#89DDFF;">\${</span><span style="color:#A6ACCD;">crypto</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">randomUUID</span><span style="color:#A6ACCD;">()</span><span style="color:#89DDFF;">}</span><span style="color:#C3E88D;">@test.com</span><span style="color:#89DDFF;">\`</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#A6ACCD;">  </span><span style="color:#F07178;">password</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">Password123</span><span style="color:#89DDFF;">&#39;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span><span style="color:#A6ACCD;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span></code></pre></div><p>Avoid generating random data directly inside test files.</p><h2 id="api-setup-vs-ui-setup" tabindex="-1">API Setup vs UI Setup <a class="header-anchor" href="#api-setup-vs-ui-setup" aria-hidden="true">#</a></h2><p>A common mistake is preparing test state through the UI:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki"><code><span class="line"><span style="color:#89DDFF;">await</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">createUserThroughUI</span><span style="color:#A6ACCD;">()</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">await</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">loginThroughUI</span><span style="color:#A6ACCD;">()</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">await</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">createCartThroughUI</span><span style="color:#A6ACCD;">()</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span></code></pre></div><p>This increases execution time and introduces unnecessary flakiness.</p><p>A better approach is API-based setup:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki"><code><span class="line"><span style="color:#89DDFF;">await</span><span style="color:#A6ACCD;"> apiClient</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">createUser</span><span style="color:#A6ACCD;">()</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">await</span><span style="color:#A6ACCD;"> apiClient</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">createCart</span><span style="color:#A6ACCD;">()</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span></code></pre></div><p>This is faster, more reliable, and easier to maintain.</p><p>Rule: Use UI to test UI. Use APIs to prepare test data.</p><h2 id="api-vs-database-seeding" tabindex="-1">API vs Database Seeding <a class="header-anchor" href="#api-vs-database-seeding" aria-hidden="true">#</a></h2><p>API setup should be the default choice because it follows real application behavior and is easier to maintain.</p><p>Database seeding can be useful when APIs are unavailable or complex state setup is required, but it comes with trade-offs:</p><ul><li>schema dependency</li><li>maintenance overhead</li><li>bypassing business logic</li><li>environment access limitations</li></ul><p>Practical preference:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki"><code><span class="line"><span style="color:#A6ACCD;">API setup &gt; DB seeding &gt; UI setup</span></span>
<span class="line"><span style="color:#A6ACCD;"></span></span></code></pre></div><h2 id="test-independence" tabindex="-1">Test Independence <a class="header-anchor" href="#test-independence" aria-hidden="true">#</a></h2><p>Every test should be self-contained. Avoid workflows where one test creates data and another depends on it.</p><p>Bad example:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki"><code><span class="line"><span style="color:#A6ACCD;">Test A creates user</span></span>
<span class="line"><span style="color:#A6ACCD;">Test B updates user</span></span>
<span class="line"><span style="color:#A6ACCD;">Test C deletes user</span></span>
<span class="line"><span style="color:#A6ACCD;"></span></span></code></pre></div><p>This creates execution dependency and parallel failures. Each test should own its own data.</p><h2 id="cleanup-strategy" tabindex="-1">Cleanup Strategy <a class="header-anchor" href="#cleanup-strategy" aria-hidden="true">#</a></h2><p>Two common approaches work well.</p><p>Disposable data is usually the simplest\u2014create unique data and allow scheduled cleanup processes to remove it later.</p><p>If cleanup is required immediately, use explicit teardown:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki"><code><span class="line"><span style="color:#82AAFF;">afterEach</span><span style="color:#A6ACCD;">(</span><span style="color:#C792EA;">async</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">()</span><span style="color:#A6ACCD;"> </span><span style="color:#C792EA;">=&gt;</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#F07178;">  </span><span style="color:#89DDFF;">await</span><span style="color:#F07178;"> </span><span style="color:#A6ACCD;">apiClient</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">deleteUser</span><span style="color:#F07178;">()</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span><span style="color:#A6ACCD;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span></code></pre></div><p>Choose the strategy based on environment constraints.</p><h2 id="authentication-state" tabindex="-1">Authentication State <a class="header-anchor" href="#authentication-state" aria-hidden="true">#</a></h2><p>Repeated UI login slows down test execution.</p><p>Use Playwright authentication state reuse:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki"><code><span class="line"><span style="color:#A6ACCD;">storageState.json</span></span>
<span class="line"><span style="color:#A6ACCD;"></span></span></code></pre></div><p>This speeds up stable authentication scenarios significantly.</p><p>However, avoid sharing mutable authenticated sessions across parallel tests.</p><h2 id="parallel-execution" tabindex="-1">Parallel Execution <a class="header-anchor" href="#parallel-execution" aria-hidden="true">#</a></h2><p>Parallel execution requires collision-safe data. Avoid:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki"><code><span class="line"><span style="color:#A6ACCD;">qa@test.com</span></span>
<span class="line"><span style="color:#A6ACCD;"></span></span></code></pre></div><p>Prefer:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki"><code><span class="line"><span style="color:#A6ACCD;">qa-\${crypto.randomUUID()}@test.com</span></span>
<span class="line"><span style="color:#A6ACCD;"></span></span></code></pre></div><p>Shared static data becomes a major source of failures as suites scale.</p><h2 id="recommended-structure" tabindex="-1">Recommended Structure <a class="header-anchor" href="#recommended-structure" aria-hidden="true">#</a></h2><p>A clean minimal setup:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki"><code><span class="line"><span style="color:#A6ACCD;">utils/</span></span>
<span class="line"><span style="color:#A6ACCD;">  apiClient.ts</span></span>
<span class="line"><span style="color:#A6ACCD;">  dataFactory.ts</span></span>
<span class="line"><span style="color:#A6ACCD;">  env.ts</span></span>
<span class="line"><span style="color:#A6ACCD;"></span></span>
<span class="line"><span style="color:#A6ACCD;">fixtures/</span></span>
<span class="line"><span style="color:#A6ACCD;">  authenticatedUser.ts</span></span>
<span class="line"><span style="color:#A6ACCD;"></span></span>
<span class="line"><span style="color:#A6ACCD;">test-data/</span></span>
<span class="line"><span style="color:#A6ACCD;">  static-users.json</span></span>
<span class="line"><span style="color:#A6ACCD;"></span></span></code></pre></div><h2 id="final-takeaway" tabindex="-1">Final Takeaway <a class="header-anchor" href="#final-takeaway" aria-hidden="true">#</a></h2><p>Reliable Playwright automation is not only about writing good tests. It is about controlling test state. Poor test data strategy is one of the biggest causes of flaky automation at scale.</p>`,62),p=[t];function o(c,r,i,d,y,D){return e(),a("div",null,p)}const A=s(l,[["render",o]]);export{C as __pageData,A as default};
